import xml.etree.ElementTree as ET
tree = ET.parse('/work/output/artifacts/skill-bpmn-error-event-subprocess/PaymentErrorHandling.bpmn')
root = tree.getroot()
ns = {
    'bpmn': 'http://www.omg.org/spec/BPMN/20100524/MODEL',
    'bpmndi': 'http://www.omg.org/spec/BPMN/20100524/DI',
}

errors = []

# Collect all IDs
all_ids = {el.get('id') for el in root.iter() if el.get('id')}

# 1. Root namespace
assert 'http://www.omg.org/spec/BPMN/20100524/MODEL' in root.tag, 'Wrong root namespace'

# 2. BPMNDiagram exists
diagrams = root.findall('.//bpmndi:BPMNDiagram', ns)
assert len(diagrams) == 1, f'Expected 1 BPMNDiagram, got {len(diagrams)}'

# Collect shaped/edged elements
shaped = {s.get('bpmnElement') for s in root.findall('.//bpmndi:BPMNShape', ns)}
edged  = {e.get('bpmnElement') for e in root.findall('.//bpmndi:BPMNEdge', ns)}

# 3. Every flow node has a shape
proc = root.find('bpmn:process', ns)
for tag in ['startEvent','endEvent','task','exclusiveGateway','subProcess']:
    for el in proc.iter('{http://www.omg.org/spec/BPMN/20100524/MODEL}' + tag):
        if el.get('id') not in shaped:
            errors.append(f'Missing shape for {tag} id={el.get(\"id\")}')

# 4. Every sequence flow has an edge
for sf in proc.iter('{http://www.omg.org/spec/BPMN/20100524/MODEL}sequenceFlow'):
    if sf.get('id') not in edged:
        errors.append(f'Missing edge for sequenceFlow id={sf.get(\"id\")}')

# 5. sourceRef/targetRef/errorRef resolve
for sf in root.iter('{http://www.omg.org/spec/BPMN/20100524/MODEL}sequenceFlow'):
    for attr in ('sourceRef','targetRef'):
        ref = sf.get(attr)
        if ref and ref not in all_ids:
            errors.append(f'Unresolved {attr}={ref}')
for eed in root.iter('{http://www.omg.org/spec/BPMN/20100524/MODEL}errorEventDefinition'):
    ref = eed.get('errorRef')
    if ref and ref not in all_ids:
        errors.append(f'Unresolved errorRef={ref}')

# 6. Error end event has errorRef
for ee in root.iter('{http://www.omg.org/spec/BPMN/20100524/MODEL}endEvent'):
    defs = list(ee.iter('{http://www.omg.org/spec/BPMN/20100524/MODEL}errorEventDefinition'))
    for d in defs:
        if not d.get('errorRef'):
            errors.append(f'Error end event {ee.get(\"id\")} missing errorRef')

# 7. bpmn:error has errorCode
for err in root.iter('{http://www.omg.org/spec/BPMN/20100524/MODEL}error'):
    if not err.get('errorCode'):
        errors.append(f'bpmn:error {err.get(\"id\")} missing errorCode')

# 8. Event subprocess has exactly one start event with event definition
sub = proc.find('{http://www.omg.org/spec/BPMN/20100524/MODEL}subProcess[@triggeredByEvent=\"true\"]')
if sub is not None:
    starts = list(sub.findall('{http://www.omg.org/spec/BPMN/20100524/MODEL}startEvent'))
    if len(starts) != 1:
        errors.append(f'Event subprocess must have exactly 1 start event, found {len(starts)}')
    else:
        se = starts[0]
        evdefs = [c for c in se if 'EventDefinition' in c.tag]
        if not evdefs:
            errors.append('Event subprocess start event missing event definition')
        isInterrupting = se.get('isInterrupting')
        if isInterrupting == 'false':
            errors.append('Event subprocess error start event should be interrupting')

# 9. XOR gateway: non-default flows have conditions; one default
for gw in proc.iter('{http://www.omg.org/spec/BPMN/20100524/MODEL}exclusiveGateway'):
    default_flow = gw.get('default')
    outgoing = [o.text.strip() for o in gw if o.tag.endswith('outgoing')]
    for flow_id in outgoing:
        if flow_id == default_flow:
            continue
        sf = root.find(f'.//*[@id=\"{flow_id}\"]')
        if sf is not None:
            cond = sf.find('{http://www.omg.org/spec/BPMN/20100524/MODEL}conditionExpression')
            if cond is None:
                errors.append(f'Non-default flow {flow_id} on XOR gateway {gw.get(\"id\")} missing conditionExpression')

if errors:
    print('ERRORS:')
    for e in errors:
        print(' ', e)
else:
    print('VALID - all structural checks passed')
"

